Date: Sat, 21 Nov 2026 17:23:04 +0100
Subject: [PATCH] applets/mediaframe: list remote folders through KIO

Folders on remote locations like SMB shares were checked and listed with
QDir, which only knows local paths, so they were treated as one broken
file and nothing was shown. List them with KIO instead and add the images.

BUG: 508225
---
 applets/mediaframe/mediaframe.cpp | 61 ++++++++++++++++++++++++++++---
 applets/mediaframe/mediaframe.h   |  5 +++
 2 files changed, 61 insertions(+), 5 deletions(-)

diff --git a/applets/mediaframe/mediaframe.cpp b/applets/mediaframe/mediaframe.cpp
index ff7381136..5d343ebde 100644
--- a/applets/mediaframe/mediaframe.cpp
+++ b/applets/mediaframe/mediaframe.cpp
@@ -19,6 +19,7 @@
 #include <QTime>
 #include <QUrl>

+#include <KIO/ListJob>
 #include <KIO/StoredTransferJob>

 MediaFrame::MediaFrame(QObject *parent)
@@ -149,19 +150,69 @@ void MediaFrame::add(const QString &path, AddOption option)
         Q_EMIT countChanged();
     } else {
         if (url.isValid() && !url.isLocalFile()) {
-            qCDebug(PLASMA_MEDIAFRAME) << "Adding" << url.toString() << "as remote file";
-            paths.append(path);
-            m_pathMap.insert(path, paths);
-            m_allFiles.append(path);
-            Q_EMIT countChanged();
+            if (QDir::match(m_filters, url.fileName())) {
+                addRemoteFile(path);
+            } else {
+                addRemoteDir(path, option);
+            }
         } else {
             qCWarning(PLASMA_MEDIAFRAME) << "Path" << path << "is not a valid file url or directory";
         }
     }
 }

+void MediaFrame::addRemoteFile(const QString &path)
+{
+    qCDebug(PLASMA_MEDIAFRAME) << "Adding" << path << "as remote file";
+    m_pathMap.insert(path, {path});
+    m_allFiles.append(path);
+    Q_EMIT countChanged();
+}
+
+void MediaFrame::addRemoteDir(const QString &path, AddOption option)
+{
+    const QUrl url(path);
+    KIO::ListJob *job = option == AddOption::RECURSIVE ? KIO::listRecursive(url, KIO::HideProgressInfo, {}) : KIO::listDir(url, KIO::HideProgressInfo, {});
+    m_listJobs.insert(job);
+
+    QString dirPath = url.path();
+    if (!dirPath.endsWith(QLatin1Char('/'))) {
+        dirPath += QLatin1Char('/');
+    }
+
+    connect(job, &KIO::ListJob::entries, this, [this, path, url, dirPath](KIO::Job *, const KIO::UDSEntryList &entries) {
+        for (const KIO::UDSEntry &entry : entries) {
+            const QString name = entry.stringValue(KIO::UDSEntry::UDS_NAME);
+            if (entry.isDir() || !QDir::match(m_filters, name.section(QLatin1Char('/'), -1))) {
+                continue;
+            }
+            QUrl fileUrl = url;
+            fileUrl.setPath(dirPath + name);
+            const QString filePath = fileUrl.toString();
+            m_pathMap[path].append(filePath);
+            m_allFiles.append(filePath);
+            Q_EMIT countChanged();
+        }
+    });
+    connect(job, &KJob::result, this, [this, path](KJob *job) {
+        m_listJobs.remove(job);
+        if (job->error()) {
+            // Not a folder we can list, try it as a single file
+            addRemoteFile(path);
+        } else if (!m_pathMap.contains(path)) {
+            qCWarning(PLASMA_MEDIAFRAME) << "No images found in directory" << path;
+        } else {
+            qCDebug(PLASMA_MEDIAFRAME) << "Added" << m_pathMap.value(path).count() << "files from" << path;
+        }
+    });
+}
+
 void MediaFrame::clear()
 {
+    for (KJob *job : std::as_const(m_listJobs)) {
+        job->kill(KJob::Quietly);
+    }
+    m_listJobs.clear();
     m_pathMap.clear();
     m_allFiles.clear();
     Q_EMIT countChanged();
diff --git a/applets/mediaframe/mediaframe.h b/applets/mediaframe/mediaframe.h
index 5ba526932..c7c672853 100644
--- a/applets/mediaframe/mediaframe.h
+++ b/applets/mediaframe/mediaframe.h
@@ -11,6 +11,7 @@
 #include <QHash>
 #include <QJSValue>
 #include <QObject>
+#include <QSet>
 #include <QString>
 #include <QStringList>
 #include <qqmlregistration.h>
@@ -79,6 +80,9 @@ private Q_SLOTS:
     void slotFinished(KJob *job);

 private:
+    void addRemoteFile(const QString &path);
+    void addRemoteDir(const QString &path, AddOption option);
+
     int random(int min, int max);
     QString getCacheDirectory();
     QString hash(const QString &str);
@@ -86,6 +90,7 @@ private:
     QStringList m_filters;
     QHash<QString, QStringList> m_pathMap;
     QStringList m_allFiles;
+    QSet<KJob *> m_listJobs;
     QString m_watchFile;
     QFileSystemWatcher m_watcher;

